type Config = { retries: number; mode: 'r' | 'w'; tags: string[] };

function mergeConfig(defaults: Config, override: any): Config {
  const out = defaults;
  for (const k in override) {
    out[k as keyof Config] = override[k];
  }
  return out;
}

const base: Config = { retries: 3, mode: 'r', tags: ['a'] };
const merged = mergeConfig(base, { retries: '5', extra: true });
